function CityModal({close,setCity}){const [q,setQ]=useState('');let list=cities.filter(c=>c.toLowerCase().includes(q.toLowerCase()));return <div className="modalbg" onClick={close}><div className="modal" onClick={e=>e.stopPropagation()}><button className="close" onClick={close}><X/></button><h2>Select your city</h2><p>See decorations available near you</p><input className="cityinput" placeholder="Search city..." value={q} onChange={e=>setQ(e.target.value)}/><h4>Popular cities</h4><div className="citygrid">{list.map(c=><button key={c} onClick={()=>{setCity(c);close()}}>{c}</button>)}</div></div></div>}
function ProductCard({p}){const {wish,toggle}=useContext(AppContext);const productPath=p.path||'/product/'+p.id;const waMsg=encodeURIComponent('Hi! I am interested in: '+p.title);return <article className="card"><Link to={productPath}><div className="pic"><img src={p.img} loading="lazy" alt={p.title}/>{p.tag&&<label>{p.tag}</label>}</div></Link><button className={'heart '+(wish.some(x=>x.id===p.id)?'on':'')} onClick={()=>toggle(p)}><Heart size={18} fill="currentColor"/></button><Link to={productPath}><h3>{p.title}</h3></Link><div className="cardBottom"><div className="rating"><Star size={14} fill="currentColor"/> {p.rating} <span>({p.reviews})</span></div><a className="waBtn" href={`https://wa.me/919999999999?text=${waMsg}`} target="_blank" rel="noreferrer"><WhatsAppIcon/> WhatsApp</a></div></article>}
