function PageSEO({title='The Balloon Atelier | Event Decorations & Balloon Decor',description='Beautiful event decorations and balloon setups delivered by verified decorators across India.',schema}){useEffect(()=>{document.title=title;const meta=document.querySelector('meta[name="description"]');if(meta) meta.setAttribute('content',description);let script=document.getElementById('page-schema');if(schema){if(!script){script=document.createElement('script');script.id='page-schema';script.type='application/ld+json';document.head.appendChild(script)}script.textContent=JSON.stringify(schema)}else if(script) script.remove();return()=>{if(schema) document.getElementById('page-schema')?.remove()}},[title,description,schema]);return null}
