function Wishlist(){const {wish}=useContext(AppContext);return <main className="listing"><h1>Your wishlist</h1>{wish.length?<div className="grid">{wish.map(p=><ProductCard p={p} key={p.id}/>)}</div>:<div className="empty"><Heart size={44}/><h2>Save your favourites here</h2><Link className="btn" to="/">Explore decorations</Link></div>}</main>}
createRoot(document.getElementById('root')).render(<BrowserRouter><App/></BrowserRouter>);
